{"code":"import pandas as pd, statsmodels.formula.api as smf
D=pd.read_csv('data/explore.csv')
xs=['vitamin_d','sleep_hours','steps_k','bmi','crp_level','dose_mg','age_decades','sodium_mmol','hdl','stress_index']
for x in xs:
 m=smf.ols(f'recovery_score ~ {x} + C(hospital)',D).fit()
 print(x, round(m.params[x],4),round(m.pvalues[x],5),round(m.rsquared,3))"}
